import type { Db } from "../db.ts";

export interface RedemptionInput {
  orderId: number;
  couponCode: string;
  discountCents: number;
  finalAmountCents: number;
  createdAt: string;
}

/** Records coupon redemptions. The redemption and its side effects are one atomic unit. */
export class CouponRedemptionRepository {
  constructor(private readonly db: Db) {}

  /**
   * Applies an already-validated coupon to an order in a single transaction:
   * updates the order amounts/coupon code, records the redemption, and bumps
   * the coupon's used_count. Rolls everything back if any step throws.
   */
  redeem(input: RedemptionInput): void {
    this.db.exec("BEGIN");
    try {
      this.db
        .prepare(
          "UPDATE orders SET discount_cents = ?, final_amount_cents = ?, coupon_code = ? WHERE id = ?",
        )
        .run(input.discountCents, input.finalAmountCents, input.couponCode, input.orderId);
      this.db
        .prepare(
          `INSERT INTO coupon_redemptions (order_id, coupon_code, discount_cents, created_at)
           VALUES (?, ?, ?, ?)`,
        )
        .run(input.orderId, input.couponCode, input.discountCents, input.createdAt);
      this.db.prepare("UPDATE coupons SET used_count = used_count + 1 WHERE code = ?").run(input.couponCode);
      this.db.exec("COMMIT");
    } catch (e) {
      this.db.exec("ROLLBACK");
      throw e;
    }
  }
}

import { describe, expect, it } from "vitest";
import { openDb } from "../src/db.ts";
import { CouponRepository } from "../src/repositories/couponRepository.ts";
import { CouponRedemptionRepository } from "../src/repositories/couponRedemptionRepository.ts";
import { OrderRepository } from "../src/repositories/orderRepository.ts";

const VALID_FROM = "2026-01-01T00:00:00Z";
const VALID_UNTIL = "2027-01-01T00:00:00Z";

describe("CouponRedemptionRepository.redeem", () => {
  it("writes the order, the redemption row, and used_count atomically", () => {
    const db = openDb();
    const coupons = new CouponRepository(db);
    const orders = new OrderRepository(db);
    coupons.insert({
      code: "SAVE20",
      type: "PERCENT",
      value: 20,
      minAmountCents: 0,
      maxDiscountCents: null,
      validFrom: VALID_FROM,
      validUntil: VALID_UNTIL,
      status: "ACTIVE",
      usageLimit: null,
    });
    const order = orders.insert("alice", 10000, "2026-10-01T00:00:00.000Z");

    new CouponRedemptionRepository(db).redeem({
      orderId: order.id,
      couponCode: "SAVE20",
      discountCents: 2000,
      finalAmountCents: 8000,
      createdAt: "2026-10-01T08:00:00.000Z",
    });

    expect(orders.findById(order.id)).toMatchObject({
      discountCents: 2000,
      finalAmountCents: 8000,
      couponCode: "SAVE20",
    });
    expect(coupons.findByCode("SAVE20")?.usedCount).toBe(1);
    expect(db.prepare("SELECT * FROM coupon_redemptions").all()).toHaveLength(1);
  });

  it("rolls back the order update when the redemption insert fails", () => {
    const db = openDb();
    const orders = new OrderRepository(db);
    const order = orders.insert("bob", 5000, "2026-10-01T00:00:00.000Z");

    expect(() =>
      new CouponRedemptionRepository(db).redeem({
        orderId: order.id,
        couponCode: "NOPE",
        discountCents: 100,
        finalAmountCents: 4900,
        createdAt: "2026-10-01T08:00:00.000Z",
      }),
    ).toThrow();

    expect(orders.findById(order.id)).toMatchObject({
      discountCents: 0,
      finalAmountCents: 5000,
      couponCode: null,
    });
    expect(db.prepare("SELECT * FROM coupon_redemptions").all()).toHaveLength(0);
  });
});

