+  it("rejects a coupon at validUntil with COUPON_EXPIRED", () => {
+    const app = createApp({ clock: fixedClock });
+    app.request("POST", "/coupons", couponRow({ validUntil: "2026-10-01T08:00:00Z" }));
+    createOrder(app, 10000);
+
+    const res = applyCoupon(app, 1, { couponCode: "SAVE20" });
+
+    expect(res.status).toBe(400);
+    expect(errorCode(res.body)).toBe("COUPON_EXPIRED");
+  });
+
+  it("rejects an exhausted coupon with COUPON_USAGE_EXHAUSTED (REQ-11)", () => {
+    const app = createApp({ clock: fixedClock });
+    app.request("POST", "/coupons", couponRow({ usageLimit: 1 }));
+    createOrder(app, 10000);
+    applyCoupon(app, 1, { couponCode: "SAVE20" });
+    createOrder(app, 10000);
+
+    const res = applyCoupon(app, 2, { couponCode: "SAVE20" });
+
+    expect(res.status).toBe(400);
+    expect(errorCode(res.body)).toBe("COUPON_USAGE_EXHAUSTED");
+    expect(app.request("GET", "/orders/2").body).toMatchObject({ discountCents: 0, finalAmountCents: 10000 });
+  });
+
+  it("rejects an order below the minimum with MINIMUM_NOT_MET (REQ-05)", () => {
+    const app = createApp({ clock: fixedClock });
+    app.request("POST", "/coupons", couponRow({ minAmountCents: 1000 }));
+    createOrder(app, 500);
+
+    const res = applyCoupon(app, 1, { couponCode: "SAVE20" });
+
+    expect(res.status).toBe(400);
+    expect(errorCode(res.body)).toBe("MINIMUM_NOT_MET");
+  });
+
+  it("leaves the database unchanged on every rejection", () => {
+    const app = createApp({ clock: fixedClock });
+    app.request("POST", "/coupons", couponRow({ minAmountCents: 1000 }));
+    createOrder(app, 500);
+
+    applyCoupon(app, 1, { couponCode: "SAVE20" });
+
+    expect(app.request("GET", "/orders/1").body).toMatchObject({
+      discountCents: 0,
+      finalAmountCents: 500,
+      couponCode: null,
+    });
+    expect(app.request("GET", "/coupons/SAVE20").body).toMatchObject({ usedCount: 0 });
+    expect(app.db.prepare("SELECT * FROM coupon_redemptions").all()).toHaveLength(0);
+  });
+});
+

